import React from 'react';

const CONFIG = {
  Low:    { color: '#27ae60', bg: '#eafaf1', icon: '✓', bar: '#27ae60' },
  Medium: { color: '#d68910', bg: '#fef9e7', icon: '!', bar: '#f39c12' },
  High:   { color: '#c0392b', bg: '#fdedec', icon: '✕', bar: '#e74c3c' },
};

const NOTE = {
  Low:    'Your risk level is low. Continue maintaining a healthy lifestyle with regular check-ups.',
  Medium: 'Moderate risk detected. Consider scheduling a check-up with your doctor soon.',
  High:   'High risk detected. Please consult a healthcare professional as soon as possible.',
};

export default function ResultCard({ result }) {
  const { probability, risk_level } = result;
  const cfg = CONFIG[risk_level];

  return (
    <div className="result-card" style={{ borderLeft: `5px solid ${cfg.color}`, background: cfg.bg }}>
      <div className="result-header">
        <span className="result-icon" style={{ background: cfg.color }}>{cfg.icon}</span>
        <h2>Prediction Result</h2>
      </div>

      <div className="result-risk" style={{ color: cfg.color }}>{risk_level} Risk</div>

      <div className="prob-label">Stroke Probability: <strong>{probability}%</strong></div>
      <div className="prob-bar-track">
        <div
          className="prob-bar-fill"
          style={{ width: `${Math.min(probability, 100)}%`, background: cfg.bar }}
        />
      </div>

      <p className="result-note">{NOTE[risk_level]}</p>

      <p className="disclaimer">
        ⚠ This tool is for informational purposes only and does not replace professional medical advice.
      </p>
    </div>
  );
}
